const Unit: number = 8
const Delta: number = 32
module Box(Origin: number, Fail: boolean) {
const FirstChoice: number = @Origin + 2
const Choices: number[] = if (@Origin > 0) { [@FirstChoice, 7] } else { [] }
const Chosen: point = coordinate(x: @Choices[0], y: @Choices[1])
export point Mark = from(source: @Chosen)
if (@Fail) {
point Fault = coordinate(x: 1 / 0, y: 0)
}
}
instance One = Box(Origin: 8, Fail: false)
point UseOne = from(source: @One::Mark)
instance Two = Box(Origin: 53, Fail: false)
point UseTwo = from(source: @Two::Mark)
instance Failed = Box(Origin: 101, Fail: true)
point UseFailed = from(source: @Failed::Mark)
point Independent = coordinate(x: 40, y: -32)

