const Unit: number = 38
const Delta: number = 26
const Zero: number = 0
const Flag: boolean = true
module Guard(Divisor: number) {
const Selected: point = if (@Divisor > 0) { coordinate(x: @Divisor, y: 3) } else { coordinate(x: 1 / 0, y: 0) }
export point Mark = from(source: @Selected)
}
instance Dormant(enabled: false) = Guard(Divisor: 0)
const Chosen: number = if (@Flag) { (@Unit + @Delta) / @Zero } else { @Unit + @Delta }
point IndependentErrorPoint = coordinate(x: @Delta / @Zero, y: 0)
const IndependentError: number = @Delta / @Zero
point Dependent = coordinate(x: @Chosen, y: 5)
point Surviving = coordinate(x: @Unit, y: @Delta)

